{"helper.ts":"// helper.ts — 纯函数，无副作用，不导入文件/进程/网络

/** 将文本切分为单词（按空白或逗号分隔） */
export function splitWords(text: string): string[] {
  return text
    .split(/[\s,]+/)
    .map((w) => w.trim())
    .filter((w) => w.length > 0);
}

/** 去重（不区分大小写）、转小写并按字典序排序 */
export function normalizeWords(words: string[]): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const w of words) {
    const lw = w.toLowerCase();
    if (!seen.has(lw)) {
      seen.add(lw);
      out.push(lw);
    }
  }
  return out.sort();
}
","index.ts":"import type { Plugin } from "../../kernel/types";
import { splitWords, normalizeWords } from "./helper";

const plugin: Plugin = {
  id: "words",
  name: "words",
  version: "1.0.0",
  onLoad(ctx) {
    ctx.register({
      kind: "tool",
      tool: {
        name: "normalize_words",
        version: "1.0.0",
        description: "将文本按空白/逗号切分为单词，去重、转小写并排序，返回逗号连接的字符串",
        permissions: { capabilities: [] },
        sideEffect: "pure",
        parameters: {
          type: "object",
          properties: {
            text: { type: "string", description: "输入文本，例如 \"BETA alpha beta\"" }
          },
          required: ["text"]
        },
        outputSchema: {
          type: "object",
          properties: {
            ok: { type: "boolean" },
            data: { type: "string", description: "逗号连接的规范化单词" }
          },
          required: ["ok", "data"]
        },
        async handler(args, tctx) {
          const text = String((args as { text?: string }).text ?? "");
          const words = normalizeWords(splitWords(text));
          return { ok: true, data: words.join(",") };
        }
      }
    });
  }
};

export default plugin;
"}

